.ove-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.ove-root,.ove-root *,.ove-root *::before,.ove-root *::after{box-sizing:border-box}
.ove-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.ove-root img{display:block;border:0;max-width:none}
.ove-root > [data-node-id]{will-change:transform}
.ove-root [hidden]{display:none!important}
.ove-root [data-sh-theme="light"]{display:none!important}
.ove-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.ove-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
.ove-root .n94_7591{align-content:stretch;display:flex;align-items:center;justify-content:space-between;position:relative;flex-shrink:0;width:100%;height:24px}
.ove-root .n94_7598{align-content:stretch;display:flex;height:24px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:70px;background-image:linear-gradient(132.2369543823071deg, color-mix(in srgb, var(--wa-point, rgb(76 174 252)) 20%, transparent) 50%, color-mix(in srgb, var(--wa-point, rgb(76 174 252)) 0%, transparent) 50%), linear-gradient(65.20586433519688deg, color-mix(in srgb, var(--wa-point, rgb(26 155 209)) 50%, transparent) 11.534%, color-mix(in srgb, var(--wa-point, rgb(18 69 197)) 50%, transparent) 98.937%)}
.ove-root .n94_7598::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-point, #3485a9);border-radius:inherit;pointer-events:none}
.ove-root .n94_7599{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:24px}
.ove-root .n94_7600{align-content:stretch;display:flex;height:24px;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:70px;background-image:linear-gradient(132.2369543823071deg, color-mix(in srgb, var(--wa-point, rgb(76 174 252)) 20%, transparent) 50%, color-mix(in srgb, var(--wa-point, rgb(76 174 252)) 0%, transparent) 50%), linear-gradient(65.20586433519688deg, color-mix(in srgb, var(--wa-point, rgb(26 155 209)) 50%, transparent) 11.534%, color-mix(in srgb, var(--wa-point, rgb(18 69 197)) 50%, transparent) 98.937%)}
.ove-root .n94_7600::after{content:"";position:absolute;inset:-0px;border:1px solid var(--wa-point, #3485a9);border-radius:inherit;pointer-events:none}
.ove-root .n94_7601{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;line-height:14px;font-style:normal;position:relative;flex-shrink:0;font-size:12px;color:var(--wa-text, #fff);white-space:nowrap;width:21px}
.ove-root[data-theme="light"] [data-name="Badge/Gas Level"] p{color:var(--wa-text, #fff)!important}
.ove-root[data-theme="light"] [data-name="Badge/Critical"] p,.ove-root[data-theme="light"] [data-name^="status-critical"] p,.ove-root[data-theme="light"] [data-name="Count/Critical"] p{color:var(--wa-danger, #ad152d)!important;font-weight:600;white-space:nowrap}
.ove-root[data-theme="light"] [data-name="Badge/Major"] p,.ove-root[data-theme="light"] [data-name^="status-major"] p,.ove-root[data-theme="light"] [data-name="Count/Major"] p{color:var(--wa-warn, #8f3f00)!important;font-weight:600;white-space:nowrap}
.ove-root[data-theme="light"] [data-name="Badge/Minor"] p,.ove-root[data-theme="light"] [data-name^="status-minor"] p,.ove-root[data-theme="light"] [data-name="Count/Minor"] p{color:var(--wa-warn, #6b4d00)!important;font-weight:600;white-space:nowrap}
.ove-root[data-theme="light"] [data-name="Badge/Warning"] p,.ove-root[data-theme="light"] [data-name^="status-warning"] p,.ove-root[data-theme="light"] [data-name="Count/Warning"] p{color:var(--wa-point, #1356b3)!important;font-weight:600;white-space:nowrap}
.ove-root[data-theme="light"] [data-name="Badge/Normal"] p,.ove-root[data-theme="light"] [data-name^="status-normal"] p,.ove-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
.ove-root[data-theme="light"] [data-name="Button/Ack"] p,.ove-root[data-theme="light"] [data-name="Button/Ack All"] p,.ove-root[data-theme="light"] [data-name="Button/Reset"] p{color:var(--wa-text, #fff)!important}
.ove-root [data-name="Header"] > [data-name="Bullet"]:has(> [data-name="Base"]){transform-origin:0 4px;transform:translate(4px,-4px) scaleY(0.8889)}
.ove-root [data-name="Event Log"] [data-name="Toolbar"] [data-name="Bullet"] > [data-name]{translate:2px 0}
.ove-root [data-name="Header"] > [data-name="Bullet"]:not(:has(> [data-name="Base"])){transform-origin:0 1.83px;transform:translate(2px,-4.17px) scaleY(0.8649)}
.ove-root[data-theme="light"] [data-name="Nav"]{background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 60%, transparent)!important}
.ove-root[data-theme="light"]{color:var(--wa-point, #15253a)}
.ove-root[data-theme="light"] [data-name="Logo Group"] [data-name="Title"]{background-image:linear-gradient(to right,var(--wa-point, #1d4fc4),var(--wa-point, #3a7ee6))!important}
.ove-root[data-theme="light"] [data-name="Clock"] [data-name="Time"]{background-image:linear-gradient(to top,var(--wa-point, #173f9e),var(--wa-point, #2e72dc) 86.843%)!important}
.ove-root[data-theme="light"] :is([data-name="Symbol"],[data-name="Floor"],[data-name="Floor Layer"],[data-name="Effect"]) img{filter:brightness(1.75) saturate(.55);opacity:.7}
.ove-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) img{content:normal!important}
.ove-root[data-theme="light"] :is([data-name="Button/Stop"],[data-name="Button/Own"],[data-name="Button/Ack"],[data-name="Button/Select"]) p{color:var(--wa-text, #fff)!important}
.ove-root[data-theme="light"] [data-name="Button/Stop"]{background:var(--wa-point, #1e86f0)!important}
.ove-root[data-theme="light"] [data-name="Button/Own"]{background:var(--wa-point, #2d6bd6)!important}
.ove-root[data-theme="light"] [data-name="Button/Ack"]{background:var(--wa-point, #24489f)!important}
.ove-root[data-theme="light"] [data-name="Button/Select"]{background:var(--wa-point, #1f6fd8)!important}
.ove-root[data-theme="light"] :is([data-name^="Node/"],[data-name="Icons"],[data-name="Node Group"]) p{text-shadow:0 0 3px #fff,0 0 6px #fff,0 0 10px rgba(255,255,255,.9)}
.ove-root[data-theme="light"] .n94_7599{color:var(--wa-point, #0f2238)}
.ove-root[data-theme="light"] .n94_7601{color:var(--wa-point, #0f2238)}
